120	function dowShort(day) {
121	  return DOW_SHORT[dow(day)];
122	}
123	function isWeekend(day) {
124	  const d = dow(day);
125	  return d === 0 || d === 6;
126	}
127	
128	// --- App state ------------------------------------------------------------
129	
130	const state = {
131	  index: null, // Map<slug, show> — the full catalogue
132	  catalogue: [], // the same catalogue as an array — what the show search scans
133	  lookups: null, // venues.json lists (genres, subgenres, …) — the search filters' options
134	  facets: null, // catalogueFacets() over the catalogue: which optional facets have data
135	  venueCoords: null, // { [venueCode]: {lat, lng} }
136	  // The working favourites, as slugs — the single source of truth for what's on
137	  // the grid and what we persist. Mutated by add (DEBUG) / remove-a-row, so the
138	  // stored list always mirrors the shows on screen, not the original upload.
139	  favSlugs: [],
140	  matched: [], // full show objects for the user's matched favourites
141	  totalFavourites: 0,
142	  missingSlugs: [],
143	  filename: "",
144	  savedAt: null,
145	  pendingUpload: null,
146	  // Date window (drives summarize()'s filter):
147	  d0: DEFAULT_D0,
148	  d1: DEFAULT_D1,
149	  // Day-hours + meal breaks + travel mode + must-sees (drive buildSchedule):
150	  dayStartMin: DEFAULT_DAY_START,
151	  dayEndMin: DEFAULT_DAY_END,
152	  mealBreaks: [
153	    { id: "lunch", enabled: true, startMin: 12 * 60 + 30, endMin: 13 * 60 + 30 },
154	    { id: "dinner", enabled: false, startMin: 18 * 60, endMin: 19 * 60 },
155	  ],
156	  // "Getting there" / "getting out" blocks (minute-of-day), applied to the first
157	  // (arrival) and last (departure) day of the trip window. Like meal breaks but
158	  // date-specific — the dates are derived from d0/d1 at plan time. Drag the block
159	  // edge on the schedule to set how much of the day travel eats.
160	  arrival: { endMin: 11 * 60, enabled: true },      // no shows before this on day one
161	  departure: { startMin: 22 * 60, enabled: true },  // no shows after this on the last day
162	  mode: "walk",
163	  // Must-sees, keyed by slug. Value `true` = pin the show (the scheduler picks a
164	  // performance); a slotKey string = pin that one specific performance. Click a
165	  // show name to toggle the first, click a performance mark to toggle the second.
166	  forced: new Map(),
167	  // Populated once per upload by buildCalendar():
168	  laneRefs: [], // [{ slug, el, statusEl }] in display (sorted) order
169	  layout: { trackLeft: 0, trackWidth: 0, dayW: 0 },
170	  dayHeaderBuilt: false,
171	  // The latest plan.
172	  schedule: null,
173	  scheduledSlugs: new Set(),
174	  // slug -> slotKey of the one performance the plan actually set for that show,
175	  // so the grid can ring the chosen day/time (not just flag the whole lane).
176	  selectedSlot: new Map(),
177	  diag: null, // latest placementDiagnostics(): which controls block which shows
178	  schedAxis: null, // { axisTopMin, axisBottomMin, hourPx, headPx } for overlay dragging
179	  // Build version + reschedule-timing telemetry (surfaced in the header pill).
180	  version: null,
181	  perf: { count: 0, sum: 0, last: 0, min: Infinity, max: 0 },
182	};
183	
184	// --- Data loading + rehydration ---------------------------------------
185	//
186	// The planner downloads two files: the compact catalogue (shows.min.json, packed
187	// by scraper/normalize.py) and the shared lookups (venues.json). rehydrateShows()
188	// (./lib/hydrate.js) unpacks the first against the second back into the full
189	// records the engine expects — every enum is an index into a venues.json list,
190	// venueName is rebuilt from the venue code + room, dates are MMDD ints, and the
191	// bare image GUID gets its host prefix re-attached — so the rest of the app sees
192	// a ready-to-use catalogue identical in shape to the old shows.json.
193	
194	let dataPromise = null;
195	
196	function loadData() {
197	  dataPromise = (async () => {
198	    // Both files are required to rehydrate: the compact catalogue and the lookups
199	    // it indexes into. Fetch them together.
200	    const [wire, lookups] = await Promise.all([
201	      fetchJson(DATA_URL),
202	      fetchJson(VENUES_URL),
203	    ]);
204	    state.venueCoords = lookups.venues || null; // venue map drives travel legs/gaps
205	    state.lookups = lookups;
206	    state.catalogue = rehydrateShows(wire, lookups, YEAR);
207	    state.index = buildIndex(state.catalogue);
208	    state.facets = catalogueFacets(state.catalogue);
209	    initSearchUI();
210	    restoreStoredFavourites();
211	    return state.index;
212	  })();
213	  dataPromise.catch(() => {});
214	  return dataPromise;
215	}
216	
217	async function fetchJson(url) {
218	  const res = await fetch(url);
219	  if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
220	  return res.json();
221	}
222	
223	async function ensureData() {
224	  if (state.index) return state.index;
225	  if (!dataPromise) loadData();
226	  $("errorState").hidden = true;
227	  $("loadingState").hidden = false;
228	  try {
229	    return await dataPromise;
230	  } catch (err) {
231	    dataPromise = null;
232	    throw err;
233	  } finally {
234	    $("loadingState").hidden = true;
235	  }
236	}
