706	function laneStatus(show, filter, sets) {
707	  if (sets.scheduled) return { kind: "scheduled" };
708	  const perfs = show.performances || [];
709	  const inWindow = perfs.filter((p) => p.date >= filter.dateStart && p.date <= filter.dateEnd);
710	  const availInWindow = inWindow.filter((p) => p.available);
