714	    const late = sets.lateSet.has(show.slug);
715	    // A single culprit reads cleanly; a mix (some too early, some too late, or a
716	    // meal break / clash) falls back to the honest "Can't fit".
717	    if (early && !late) return { kind: "early" };
718	    if (late && !early) return { kind: "late" };
