724	  // run, whereas bad dates are exactly what the date scrubber fixes.
725	  const runSold = perfs.length > 0 && perfs.every((p) => p.soldOut);
726	  const windowSold = inWindow.length > 0 && inWindow.every((p) => p.soldOut);
727	  if (runSold || windowSold) return { kind: "sold" };
728	  return { kind: "baddates" };
