286	/* ============ Show search (build / top up the grid one show at a time) ==== */
287	/* One component, two homes: the bottom of the empty intake stage and the
288	   bottom line of the availability grid (plan.js moves the #showSearch node
289	   between the slots). Everything here is container-independent on purpose —
290	   the bar must look the same before and after the grid has data. */
291	.ss-slot { width: 100%; }
292	.ss-slot:empty { display: none; }
293	#ssSlotIntake { max-width: 640px; }
294	#ssSlotCal { margin-top: 14px; }
295	.show-search { position: relative; text-align: left; }
296	.ss-bar {
297	  display: flex; align-items: center; gap: 8px;
298	  background: #fff; border: 1px solid var(--line); border-radius: 12px;
299	  padding: 7px 8px 7px 14px; box-shadow: var(--shadow-soft);
300	  transition: border-color 0.12s ease, box-shadow 0.12s ease;
