312	.ss-tools-btn {
313	  flex: 0 0 auto; display: inline-flex; align-items: center; gap: 6px;
314	  font: inherit; font-size: 0.78rem; font-weight: 600; color: var(--muted);
315	  background: var(--bg); border: 1px solid var(--line); border-radius: 999px;
316	  padding: 6px 12px; cursor: pointer; white-space: nowrap;
317	}
318	.ss-tools-btn:hover { color: var(--ink); border-color: #d5d9e2; }
319	.ss-tools-btn[aria-expanded="true"] {
320	  color: var(--violet-dark); border-color: var(--violet);
321	  background: rgba(108, 76, 241, 0.07);
322	}
323	.ss-tools-btn:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
324	/* Active-filter count on the tools button. */
325	.ss-badge {
326	  min-width: 17px; height: 17px; border-radius: 999px; padding: 0 5px;
327	  display: grid; place-items: center;
