329	}
330	
331	/* The expanded line of search tools above the box. */
332	.ss-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 8px; }
333	.ss-filter { font-size: 0.78rem; padding: 6px 8px; max-width: 176px; }
334	.ss-filter.is-set {
335	  border-color: var(--violet); color: var(--violet-dark);
336	  background: rgba(108, 76, 241, 0.05);
337	}
338	.ss-filter:disabled { opacity: 0.55; cursor: not-allowed; }
339	.ss-reset {
340	  font: inherit; font-size: 0.76rem; font-weight: 600; color: var(--muted);
341	  background: none; border: none; padding: 2px 4px; cursor: pointer;
342	  text-decoration: underline; text-underline-offset: 2px; text-decoration-color: #c6cdda;
343	}
344	.ss-reset:hover { color: var(--ink); text-decoration-color: currentColor; }
345	.ss-reset:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; border-radius: 4px; }
346	
347	/* The results popup — an overlay under the bar, never a layout push. */
348	.ss-pop {
349	  position: absolute; left: 0; right: 0; top: calc(100% + 6px); z-index: 45;
350	  background: var(--paper); border: 1px solid var(--line); border-radius: 12px;
351	  box-shadow: 0 18px 40px rgba(16, 24, 40, 0.18);
352	  max-height: 342px; overflow-y: auto; overscroll-behavior: contain;
