378	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
379	}
380	.ss-empty, .ss-foot { margin: 0; padding: 10px 14px; font-size: 0.8rem; color: var(--muted); }
381	.ss-foot { border-top: 1px solid var(--line); padding: 7px 14px; font-size: 0.72rem; }
382	
383	/* The intake stage's "or" divider + one-line lead into the search path. */
384	.intake-or {
