415	#screen2.is-collapsed .cal-legend { display: none; }
416	
417	/* The favourites provenance line: what's loaded, plus quiet replace/clear
418	   actions — deliberately low-key, no button chrome, no accent colour. */
419	.fav-line {
420	  display: flex; align-items: baseline; gap: 4px 8px; flex-wrap: wrap;
421	  margin: 0; font-size: 0.85rem; color: var(--muted);
422	}
423	.fav-action {
424	  font: inherit; font-size: 0.82rem; color: var(--muted);
425	  background: none; border: none; padding: 0; cursor: pointer;
426	  text-decoration: underline; text-underline-offset: 2px;
427	  text-decoration-color: #c6cdda;
428	}
429	.fav-action:hover { color: var(--ink); text-decoration-color: currentColor; }
