444	  100% { transform: scale(1); }
445	}
446	.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
447	.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }
448	
449	/* The availability-status legend colours mirror edfringe.com's own day-picker
450	   legend (see plan.js segClass / the --fr-* tokens below). */
451	.opt-select {
452	  font: inherit; font-size: 0.84rem; font-weight: 600; color: var(--ink);
453	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
454	  padding: 7px 10px; cursor: pointer;
455	}
456	.opt-select:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
457	.btn-sm { padding: 8px 14px; font-size: 0.84rem; border-radius: 10px; box-shadow: 0 4px 12px rgba(108, 76, 241, 0.22); }
458	.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
459	.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
460	.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
461	.lg-avail i   { background: var(--fr-avail); }
462	.lg-2for1 i   { background: var(--fr-2for1-weave); }
463	.lg-preview i { background: var(--fr-preview); }
464	.lg-free i    { background: var(--fr-free); }
465	.lg-event i   { background: var(--fr-event); }
466	.lg-noalloc i { background: var(--fr-noalloc); }
467	
468	/* --- The calendar canvas --- */
469	/* .cal-wrap is the scroll container: the sticky block (window-control rail +
470	   day header) stays at its top while the lane list scrolls beneath it. The
471	   toolbar/hero-count above are outside this container entirely, so they never
472	   scroll away either. */
473	.cal-wrap {
474	  position: relative; margin-top: 20px;
475	  /* Deliberately shallow: the calendar is now the "pick your window" step that
476	     feeds the planner below it, so it stays compact and scrolls internally
477	     rather than pushing the Plan card off-screen. */
478	  max-height: 38vh; overflow-y: auto; overflow-x: hidden;
479	  border-radius: 10px;
480	}
481	.cal-inner { position: relative; }
482	
483	.cal-sticky { position: sticky; top: 0; z-index: 4; background: var(--paper); }
484	
485	/* minmax(0, …) on the day track lets the 31 columns shrink to the available
486	   width instead of holding their content's min-width and forcing the whole grid
487	   (day header + lanes) to overflow — which clipped the "In plan" column and the
488	   window flags on a narrower page. */
489	.cal-row { display: grid; grid-template-columns: 184px minmax(0, 1fr) 104px; gap: 0 12px; align-items: center; }
490	
491	.cal-head { border-bottom: 1px solid var(--line); padding-bottom: 6px; }
492	.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
493	.days { display: grid; grid-template-columns: repeat(31, minmax(0, 1fr)); gap: 3px; }
494	.day-col { text-align: center; line-height: 1.15; }
495	.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
496	.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
497	.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
498	.day-col.pre .day-num, .day-col.pre .day-dow { color: #cfd4de; }
499	
500	.lanes { position: relative; z-index: 1; }
501	/* One tight single-line row per show — this screen is an overview of the shows
502	   you want, so each row is deliberately compact (title only, no meta line). */
503	.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
504	.lane:last-child { border-bottom: none; }
505	.lane-label { min-width: 0; display: flex; align-items: center; gap: 4px; }
506	.lane-title {
507	  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
508	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
509	}
510	/* The must-see pin — hidden unless the row is forced into the plan. */
511	.lane-pin { flex: 0 0 auto; font-size: 0.72rem; display: none; }
512	.lane--forced .lane-pin { display: inline; }
513	/* Drop this show from the list. Pushed to the right of the label, faint until
514	   the row is hovered/focused so it stays out of the way on a dense grid. */
515	.lane-remove {
516	  flex: 0 0 auto; margin-left: auto;
517	  border: 0; background: none; padding: 0 2px; cursor: pointer;
518	  font-size: 0.95rem; line-height: 1; color: #c2c8d2;
519	  opacity: 0.35; transition: opacity 0.12s ease, color 0.12s ease;
520	}
521	.lane:hover .lane-remove, .lane-remove:focus-visible { opacity: 1; }
522	.lane-remove:hover { color: var(--warn); }
523	/* A scheduled row gets a faint green wash so the grid mirrors the plan (the
524	   Status column carries the ✓ In plan text; no coloured left bar). */
525	.lane--scheduled { background: rgba(5, 150, 105, 0.05); }
526	/* The name and the performance marks are the two click targets (lock the show /
527	   lock that performance). The padlock cursor carries that affordance. */
528	.lane-label { cursor: var(--lock-cursor); }
529	.lane-label:hover .lane-title { text-decoration: underline; }
530	.lane-track { display: grid; grid-template-columns: repeat(31, minmax(0, 1fr)); gap: 3px; align-items: center; height: 100%; }
531	
532	/* A day cell holds one coloured segment per performance; two performances on a
533	   day render as two side-by-side segments — the split IS the "two shows that
534	   day" cue. Single-performance days read as one solid bar. */
535	.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; cursor: var(--lock-cursor); }
536	.cell:hover { box-shadow: 0 0 0 2px rgba(16, 24, 40, 0.3); }
537	.cell-multi { gap: 1.5px; }
538	.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
539	/* The performance the plan actually *set* for this show — the grid mirrors the
540	   itinerary, turning the chosen day/time into a gold bar (the higher-specificity
541	   .seg.seg--selected wins over the availability colour), so a locked-in mark
542	   reads as a little gold bar rather than a green-ringed availability chip. */
543	.seg.seg--selected, .seg.seg--pinned { background: var(--fr-locked); }
544	.seg--selected, .seg--pinned { box-shadow: inset 0 0 0 1px #e0b23a, 0 1px 2px rgba(190, 145, 20, 0.4); }
545	/* A whole-show pin: every performance gets a dashed gold border (you've forced
546	   the show in; the scheduler still picks which one, and that one goes solid gold
547	   via .seg--selected). Outline — not box-shadow — so it can be dashed; the
548	   negative offset pulls it inside the mark so overflow:hidden doesn't clip it. */
549	.seg--forced-all { outline: 1.5px dashed #e0b23a; outline-offset: -1.5px; }
550	/* A pinned exact performance: the same gold bar, plus a lock badge that sits
551	   above the mark. The badge deliberately overlaps the row above, so the pinned
552	   cell drops its overflow clip to let it escape upward. */
553	.seg--pinned { position: relative; }
554	.cell--pin { overflow: visible; }
555	.seg-pin {
556	  position: absolute; left: 50%; bottom: 100%;
557	  transform: translate(-50%, 30%);
558	  font-size: 0.82rem; line-height: 1; pointer-events: none; z-index: 6;
559	  filter: drop-shadow(0 1px 1px rgba(16, 24, 40, 0.35));
560	}
561	.seg-avail   { background: var(--fr-avail); }
562	.seg-2for1   { background: var(--fr-2for1-weave); }
563	.seg-preview { background: var(--fr-preview); }
564	.seg-free    { background: var(--fr-free); }
565	.seg-event   { background: var(--fr-event); }
566	.seg-noalloc { background: var(--fr-noalloc); }
567	/* Sold out shares the red "no allocation" mark — both mean "no online ticket". */
568	.seg-sold    { background: var(--fr-noalloc); }
569	
570	/* Fixed-height row so the pushpin (a tall glyph) can't stretch a lane taller
571	   than its neighbours — there's no vertical room for that. Content is clamped
572	   and centred; the pin sits just left of the status pill. */
573	.lane-status {
574	  font-size: 0.72rem; line-height: 1.1; text-align: center;
575	  display: flex; align-items: center; justify-content: center; gap: 2px;
576	  height: 20px; overflow: hidden;
577	}
578	.lane-status .st-pin { font-size: 0.62rem; line-height: 1; flex: 0 0 auto; }
579	.lane-status .st-plan {
580	  font-weight: 700; color: var(--ok-text); white-space: nowrap;
581	  background: var(--ok-bg); border-radius: 999px; padding: 2px 7px;
582	}
583	.lane-status .st-in { color: var(--violet-dark); font-weight: 600; white-space: nowrap; }
584	.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
585	/* "Can't fit" — catchable but crowded out; muted, no alarm. */
586	.lane-status .st-cant { color: var(--muted); font-weight: 600; white-space: nowrap; }
587	/* "Sold out" — greyed, matching the sold-out day marks. */
588	.lane-status .st-sold { color: #98a2b3; font-weight: 700; white-space: nowrap; }
589	/* "Bad dates" — a dates problem the window scrubber fixes; quiet violet. */
590	.lane-status .st-dates { color: var(--violet-dark); font-weight: 600; white-space: nowrap; }
591	/* Every show that isn't in the plan reads the same, whatever the reason (out of
592	   window, can't fit, too early/late, sold out): one dimmed title. A scheduled or
593	   forced row is never dimmed — it made the plan. Out-of-window shows also recede
594	   their day marks, to the same transparency, since none fall in your dates;
595	   in-window shows keep their marks bright (those marks still mean something). */
596	.lane:not(.lane--scheduled) .lane-title { opacity: 0.42; }
597	.lane--out:not(.lane--scheduled) .lane-track { opacity: 0.42; }
598	
599	/* --- Window controls: the rail (sticky, above the day header) --- */
600	/* All dragging lives here: the two handle tabs resize the window; the space
601	   between them slides the whole window. */
602	.win-rail { position: relative; height: 38px; }
603	/* The between-handles band both slides the window and carries the window
604	   length + the optimizer link (the old separate toolbar folded in here). */
605	.rail-band {
606	  position: absolute; top: 6px; bottom: 0;
607	  display: flex; align-items: center; justify-content: center; gap: 8px;
608	  overflow: hidden; padding: 0 8px;
609	  background: rgba(108, 76, 241, 0.07);
610	  border-radius: 8px 8px 0 0;
611	  cursor: grab; touch-action: none;
612	}
613	.rail-band:hover { background: rgba(108, 76, 241, 0.12); }
614	.rail-band:active { cursor: grabbing; }
615	/* The window length — the "grip" text; inert so a drag starts through it. */
616	.rail-len {
617	  font-size: 0.7rem; font-weight: 700; color: var(--violet-dark);
618	  white-space: nowrap; font-variant-numeric: tabular-nums; pointer-events: none;
619	}
620	/* A mild, low-key "Optimize?" link. Interactive (it opens the popover), so it
621	   re-enables pointer events the band's label opts out of. */
622	.rail-opt {
623	  font: inherit; font-size: 0.68rem; font-weight: 600; color: var(--muted);
624	  background: none; border: none; padding: 0; cursor: pointer; pointer-events: auto;
625	  text-decoration: underline; text-underline-offset: 2px; text-decoration-color: #b7bcc9;
626	  white-space: nowrap;
627	}
628	.rail-opt:hover { color: var(--violet-dark); text-decoration-color: currentColor; }
629	.rail-opt:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; border-radius: 4px; }
630	
631	/* The optimizer popover (positioned in JS, fixed, so it escapes the scroller). */
632	.rail-pop {
633	  position: fixed; z-index: 60; min-width: 224px;
634	  display: flex; flex-direction: column; gap: 12px;
635	  background: var(--paper); border: 1px solid var(--line); border-radius: 12px;
636	  padding: 14px; box-shadow: var(--shadow-soft);
