638	.rail-pop[hidden] { display: none; }
639	.rail-pop-row {
640	  display: flex; align-items: center; justify-content: space-between; gap: 12px;
641	  font-size: 0.84rem; font-weight: 600; color: var(--ink);
642	}
643	.rail-pop-row input {
644	  width: 66px; font: inherit; font-size: 0.86rem; font-weight: 600; color: var(--ink);
645	  border: 1px solid var(--line); border-radius: 10px; background: #fff; padding: 6px 8px;
646	}
647	.rail-pop-check { display: flex; align-items: center; gap: 8px; font-size: 0.84rem; color: var(--ink); cursor: pointer; }
648	.rail-pop-check input { accent-color: var(--violet); width: 15px; height: 15px; }
649	.rail-pop .btn-sm { justify-content: center; }
