652	.win-handle {
653	  position: absolute; top: 0; bottom: 0; width: 26px;
654	  transform: translateX(-50%);
655	  cursor: grab; touch-action: none; z-index: 1;
656	}
657	.win-handle:active { cursor: grabbing; }
658	/* The tab's stem: a short violet line down to the day header, continuing
659	   visually into the band edge below the header. */
660	.win-handle::before {
661	  content: ""; position: absolute; left: 50%; top: 6px; bottom: 0;
662	  width: 2px; margin-left: -1px; background: var(--violet);
663	}
664	/* The draggable knob. A raised pill button with a grip on its outer edge, so it
665	   reads as grab-and-slide rather than a static date label. Tabs anchor OUTWARD
666	   from their stem (start points left, end points right) so they never collide
667	   even when the window is dragged narrow. The "0 2px 0" layer is a solid bottom
668	   edge that gives the button height; the press state below sinks it. */
669	/* A solid violet chip planted on the stem line — reads as a little flag/marker
670	   on the date, not a text label. A quiet "From"/"To" cap disambiguates the two
671	   ends; the inner-bottom corner squares off where the chip meets its stem so it
672	   looks planted. No more grip bars. */
673	.win-flag {
674	  position: absolute; top: 2px;
675	  display: inline-flex; align-items: baseline; gap: 5px;
676	  font-size: 0.74rem; font-weight: 800; color: #fff;
677	  background: linear-gradient(180deg, #7d5cf5, var(--violet));
678	  border-radius: 9px;
679	  padding: 5px 10px; white-space: nowrap;
680	  box-shadow: 0 4px 10px rgba(90, 63, 214, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.25);
681	  font-variant-numeric: tabular-nums;
682	  cursor: grab;
683	  transition: transform 0.1s ease, box-shadow 0.1s ease, background 0.12s ease;
684	}
685	.win-flag .wf-cap {
686	  font-size: 0.56rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0.72;
687	}
688	.win-handle--start .win-flag { right: 50%; margin-right: -1px; border-bottom-right-radius: 2px; }
689	.win-handle--end .win-flag { left: 50%; margin-left: -1px; border-bottom-left-radius: 2px; }
690	.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
691	  background: linear-gradient(180deg, #6c4cf1, var(--violet-dark));
692	  transform: translateY(-1px);
693	  box-shadow: 0 6px 14px rgba(90, 63, 214, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.25);
694	}
695	/* Pressed: settle the chip for a tactile grab. */
696	.win-handle:active .win-flag {
697	  transform: translateY(0); cursor: grabbing;
698	  box-shadow: 0 2px 6px rgba(90, 63, 214, 0.4);
699	}
700	.win-handle:focus-visible { outline: none; }
701	.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.4), 0 6px 14px rgba(16, 24, 40, 0.2); }
