703	/* --- Window overlay over the lanes: purely visual, never intercepts the
704	   pointer — lane cells keep their hover tooltips. --- */
705	.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
706	.festend { position: absolute; top: 0; bottom: 0; background: rgba(234, 236, 240, 0.35); border-right: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
707	.win-dim { position: absolute; top: 0; bottom: 0; background: rgba(247, 248, 250, 0.72); }
708	.win-band {
709	  position: absolute; top: 0; bottom: 0;
710	  background: rgba(108, 76, 241, 0.05);
711	  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
712	}
713	/* Draggable grips on the band's two vertical lines — a thin ew-resize strip
714	   centred on each edge. pointer-events re-enabled here (the overlay itself is
715	   inert), so the rest of the grid keeps its cell hovers. */
716	.win-edge {
