952	  background: repeating-linear-gradient(-45deg, rgba(16,24,40,0.05) 0 6px, rgba(16,24,40,0.02) 6px 12px);
953	  border-block: 1px solid rgba(16, 24, 40, 0.08);
954	}
955	/* The two full-width draggable day boundary lines. */
956	.sch-dayline {
957	  position: absolute; left: 0; right: 0; height: 0; z-index: 6;
