966	  font-size: 0.6rem; font-weight: 700; color: #fff; background: var(--violet);
967	  border-radius: 5px; padding: 1px 6px; white-space: nowrap; pointer-events: none;
968	  font-variant-numeric: tabular-nums;
969	}
970	.sch-dayline--end .dl-flag { bottom: auto; top: 8px; }
971	.sch-dayline.dragging .dl-flag, .sch-dayline .dl-grip:hover ~ .dl-flag { background: var(--violet-dark); }
972	/* Meal-break band: draggable to move, edge handles to resize. Its background
973	   now matches the "before day starts / after day ends" zones (a neutral
974	   diagonal hatch) so every "you can't be here" region on the board reads the
975	   same; only the 🍽 label carries the meal identity. */
976	.sch-meal {
977	  position: absolute; left: 0; right: 0; z-index: 5;
