979	  cursor: grab; pointer-events: auto; touch-action: none; overflow: visible;
980	}
981	.sch-meal.dragging { cursor: grabbing; }
982	/* Pinned to the top of the band (like the day-end flag) rather than floating in
983	   the middle, so it stays put as the band is dragged / resized. */
984	.sch-meal .meal-label {
985	  position: absolute; top: 6px; left: 0; right: 0;
986	  text-align: center;
