990	/* Playful faint emoji scatter behind a blocker region (meal band, day-start /
991	   day-end zone, or trip block) — deterministic emoji on a fixed pixel grid
992	   (populateDecors). Always visible — only the swim animation below is gated on
993	   the pointer being on the board (the .is-grid-hover class). */
994	.sch-decor {
995	  position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 0;
996	  opacity: 0.22;
997	}
998	.sch-decor span { position: absolute; display: block; line-height: 1; }
999	/* While the board is live (hovering, or mid-drag) the scatter gently swims:
1000	   each emoji bobs and sways in place. `translate`/`rotate` are the independent
1001	   transform properties, so they compose with the per-span `transform`
1002	   (translate(-50%,-50%) rotate(...)) set inline — the centring + base tilt are
1003	   preserved and only a small drift is layered on. Staggered by :nth-child so
1004	   the shoal never moves in lockstep. Gated to .is-grid-hover so it costs
1005	   nothing while idle. */
1006	.schedule.is-grid-hover .sch-decor span { animation: decor-swim 4.4s ease-in-out infinite; }
1007	.schedule.is-grid-hover .sch-decor span:nth-child(2n) { animation-duration: 5.6s; animation-delay: -1.2s; }
1008	.schedule.is-grid-hover .sch-decor span:nth-child(3n) { animation-duration: 6.4s; animation-delay: -2.6s; }
1009	.schedule.is-grid-hover .sch-decor span:nth-child(5n) { animation-duration: 5s; animation-delay: -0.6s; }
1010	@keyframes decor-swim {
