1017	.sch-trip {
1018	  position: absolute; left: 0; right: 0; z-index: 5;
1019	  background: repeating-linear-gradient(-45deg, rgba(16,24,40,0.05) 0 6px, rgba(16,24,40,0.02) 6px 12px);
1020	  pointer-events: auto; touch-action: none; overflow: visible;
1021	}
