1023	  position: absolute; left: 6px; right: 6px; text-align: center;
1024	  font-size: 0.6rem; font-weight: 700; color: var(--muted);
1025	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
1026	  font-variant-numeric: tabular-nums; pointer-events: none; z-index: 1;
1027	}
1028	/* The label hugs the block's draggable inner edge: arrival just above its
1029	   bottom glyph, departure just below its top glyph (both inside the block). */
1030	.sch-trip--arrival .sch-trip-label { bottom: 4px; }
1031	.sch-trip--departure .sch-trip-label { top: 8px; }
1032	.sch-trip.dragging {
1033	  background: repeating-linear-gradient(-45deg, rgba(108,76,241,0.12) 0 6px, rgba(108,76,241,0.04) 6px 12px);
1034	}
1035	
1036	/* --- Shared drag handle: every draggable boundary (day-start/end lines, meal
1037	   edges, trip inner edge) shows the same violet line + centred grip pill, so
1038	   they all read as one grab affordance. The meal/trip resize strips straddle
