1099	/* ============ Live re-plan animation ============ */
1100	/* A newly placed show eases in; the same show rescheduled flies to its new slot
1101	   (transform set inline via FLIP); a dropped show leaves as a fading ghost. */
1102	.sch-show--enter { animation: schEnter 0.34s cubic-bezier(0.2, 0.7, 0.3, 1) both; }
1103	@keyframes schEnter {
