1127	
1128	/* ============ "Not placeable" diagnostics ============ */
1129	/* Past-midnight hour labels on the schedule axis read a touch quieter. */
1130	.sch-hour--late { color: #c9cede; font-style: italic; }
1131	/* Amber verdict for a show ruled out only by the day-hours / meal-break window. */
1132	/* "Not placeable" is too wide for the status column on one line — let it wrap
1133	   rather than clip (it's plain text, not a pill). */
1134	.lane-status .st-blocked { color: #9a6700; font-weight: 700; }
1135	.lane--blocked:not(.lane--scheduled) { background: rgba(226, 168, 21, 0.06); }
