1141	/* "⚠ Prevents N" chip next to a blocking control. */
1142	.ctl-blocked {
1143	  align-self: flex-start; font: inherit; font-size: 0.66rem; font-weight: 700;
1144	  color: #9a6700; background: #fff4d6; border: 1px solid #f0c65a; border-radius: 999px;
1145	  padding: 2px 8px; cursor: pointer; white-space: nowrap; line-height: 1.3;
1146	}
1147	.ctl-blocked:hover { background: #ffeab3; }
1148	.ctl-blocked:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
1149	.meal-blocked { align-self: center; margin-left: 2px; }
1150	/* On the schedule overlay, a boundary line / meal band that shuts shows out
1151	   turns amber and carries a small "not placeable · N" tag. */
1152	.sch-dayline--blocking { border-top-color: #e2a815; }
1153	.sch-dayline--blocking .dl-flag { background: #c77700; }
1154	/* A meal break that's blocking a show reads only from the "not placeable" badge
1155	   now — the band itself stays the calm neutral hatch, like the day-end zone. */
1156	.dl-blocked {
1157	  position: absolute; right: 4px; top: -9px; transform: translateY(-100%);
1158	  font-size: 0.56rem; font-weight: 700; color: #fff; background: #c77700;
1159	  border-radius: 5px; padding: 1px 6px; white-space: nowrap; pointer-events: auto;
1160	}
1161	.sch-dayline--end .dl-blocked { top: 1px; transform: translateY(100%); }
1162	
1163	/* The inline "(excludes N shows)" pill on a meal band's centre label. Orange,
1164	   compact, and interactive (hover it for the list) — it replaces the old corner
1165	   "not placeable · N" badge on meal bands. */
1166	.excl-pill {
1167	  pointer-events: auto; cursor: help; vertical-align: middle;
1168	  font-size: 0.56rem; font-weight: 700; color: #fff; background: #c77700;
1169	  border-radius: 5px; padding: 0 5px; white-space: nowrap;
1170	}
1171	/* The excludes-list hover popup — a narrower cousin of the show card. */
1172	.excl-pop {
1173	  position: fixed; z-index: 70; pointer-events: none; max-width: 190px;
1174	  background: var(--paper); border: 1px solid var(--line); border-radius: 10px;
1175	  box-shadow: 0 10px 26px rgba(16, 24, 40, 0.2); padding: 8px 10px;
1176	}
1177	.excl-pop-head {
1178	  font-size: 0.62rem; font-weight: 800; color: #c77700;
1179	  text-transform: uppercase; letter-spacing: 0.04em; margin-bottom: 5px;
1180	}
1181	.excl-pop-list { margin: 0; padding: 0; list-style: none; }
1182	.excl-pop-list li {
1183	  font-size: 0.72rem; color: var(--ink); line-height: 1.35;
1184	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 170px;
1185	}
1186	.excl-pop-more { margin-top: 4px; font-size: 0.66rem; font-weight: 700; color: var(--muted); }
1187	
1188	@media (prefers-reduced-motion: reduce) {
1189	  .hc-num.bump { animation: none; }
1190	  .sch-show--enter, .sch-show--moving, .sch-ghost, .sch-day--enter, .lane--flash { animation: none; transition: none; }
1191	  .schedule.is-grid-hover .sch-decor span { animation: none; }
1192	  #win.is-sliding .win-dim, #win.is-sliding .win-band,
1193	  #winRail.is-sliding .rail-band, #winRail.is-sliding .win-handle { transition: none; }
1194	  html { scroll-behavior: auto; }
1195	}
