.card {
  position: relative;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow-soft);
  transition: transform 0.14s ease, box-shadow 0.14s ease;
}
.card.is-open,
.card:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 34px rgba(34, 42, 36, 0.14);
}
/* Lift the open card (and its pop-over) above the map's stacking context. */
.card.is-open { z-index: 1500; }
.card-trigger {
  display: block;
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
  padding: 28px 22px 22px;
}

/* Pop-over panels */
.card-panel {
  position: absolute;
  z-index: 1200;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 18px 40px rgba(34, 42, 36, 0.18);
  padding: 18px 18px 20px;
}
.card-panel[hidden] { display: none; }
.panel-title {
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-size: 0.78rem;
  font-weight: 700;
  margin: 0 0 14px;
  color: var(--muted);
}
.panel-options { display: grid; gap: 4px; }
.panel-option {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 8px;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.95rem;
  font-weight: 600;
}
.panel-option:hover { background: var(--line); }
.panel-option input { flex: 0 0 auto; accent-color: var(--red); width: 16px; height: 16px; }
.panel-field-label {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted);
  margin: 12px 0 6px;
}
.panel-select {
  width: 100%;
  font: inherit;
  font-weight: 600;
  padding: 10px 12px;
  border: 2px solid var(--ink);
  border-radius: var(--radius);
  background: var(--paper);
  cursor: pointer;
}
.panel-select:disabled { opacity: 0.5; cursor: not-allowed; }
.panel-input {
  width: 100%;
  font: inherit;
  font-weight: 600;
  padding: 10px 12px;
  border: 2px solid var(--ink);
  border-radius: var(--radius);
  background: var(--paper);
}
.panel-input:disabled { opacity: 0.5; }
/* "Find on map" — resolves a typed place and closes the picker. */
.panel-find { display: inline-flex; align-items: center; gap: 6px; margin: 10px 0 2px; font: inherit; font-weight: 700; font-size: 0.85rem; color: #fff; background: var(--blue); border: none; border-radius: 12px; padding: 10px 16px; cursor: pointer; }
.panel-find:hover { filter: brightness(0.96); }
.panel-find:disabled { opacity: 0.45; cursor: not-allowed; }
.panel-find:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
.panel-range {
  width: 100%;
  accent-color: var(--red);
  cursor: pointer;
  margin: 2px 0 0;
}
.range-value {
  margin: 6px 0 2px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--ink);
}
/* Speed hint beside a travel mode, e.g. "Walking (3.3 km/h)". */
.opt-speed { font-weight: 600; font-size: 0.8rem; color: var(--muted); }
/* Genre emoji prefix in the genre dropdown options. */
.opt-ico { display: inline-block; width: 1.4em; text-align: center; }
/* Segmented control — used for the Free/Paid/Both price choice. */
.segmented { display: flex; gap: 4px; margin: 4px 0 4px; padding: 3px; background: var(--bg); border: 1px solid var(--line); border-radius: 999px; }
.seg-btn { flex: 1 1 0; font: inherit; font-weight: 700; font-size: 0.85rem; color: var(--muted); background: transparent; border: none; padding: 8px 6px; border-radius: 999px; cursor: pointer; transition: color 0.12s ease, background 0.12s ease; }
.seg-btn.is-active { color: #fff; background: var(--red); }
.seg-btn:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
.panel-title--spaced { margin-top: 16px; }
/* Reset-all-filters button at the foot of the genre panel. */
.panel-reset { display: inline-flex; align-items: center; gap: 6px; margin: 14px 0 0; font: inherit; font-weight: 700; font-size: 0.82rem; color: var(--red-dark); background: transparent; border: 1px solid var(--line); border-radius: 999px; padding: 8px 14px; cursor: pointer; }
.panel-reset:hover { border-color: var(--red); background: #fff; }
.panel-reset:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
.panel-note {
  margin: 14px 0 0;
  font-size: 0.82rem;
  color: var(--muted);
  font-style: italic;
}
.card-caret {
  display: inline-block;
  margin-top: 12px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--muted);
}

.card-label {
  text-transform: uppercase;

