1	// Tests for the catalogue search (plan/lib/search.js): facet filter semantics
2	// (including how unknown accessibility/price/age data is excluded once a
3	// filter on that facet is active), query ranking, and facet detection.
4	
5	import { test } from "node:test";
6	import assert from "node:assert/strict";
7	
8	import {
9	  ageLimitYears,
10	  showPrice,
11	  catalogueFacets,
12	  hasActiveFilters,
13	  filterShows,
14	  searchShows,
15	} from "../search.js";
16	
17	// Minimal show records — only the fields search.js reads.
18	function show(overrides) {
19	  return {
20	    slug: "s",
21	    title: "A Show",
22	    genre: "Comedy",
23	    subgenres: [],
24	    company: null,
25	    venueName: null,
26	    ageRestriction: "ZERO",
27	    free: false,
28	    ...overrides,
29	  };
30	}
31	
32	// --- accessors -------------------------------------------------------------
33	
34	test("ageLimitYears maps the enum, null for unknown", () => {
35	  assert.equal(ageLimitYears(show({ ageRestriction: "ZERO" })), 0);
36	  assert.equal(ageLimitYears(show({ ageRestriction: "EIGHTEEN" })), 18);
37	  assert.equal(ageLimitYears(show({ ageRestriction: null })), null);
38	  assert.equal(ageLimitYears(show({ ageRestriction: "MYSTERY" })), null);
39	});
40	
41	test("showPrice reads numbers and £-strings, falls back to the free flag", () => {
42	  assert.equal(showPrice(show({ price: 12 })), 12);
43	  assert.equal(showPrice(show({ price: "£12.50" })), 12.5);
44	  assert.equal(showPrice(show({ price: "from £8" })), 8);
45	  assert.equal(showPrice(show({ free: true })), 0);
46	  assert.equal(showPrice(show({ price: 5, free: true })), 5); // explicit price wins
47	  assert.equal(showPrice(show({})), null);
48	});
49	
50	// --- facet detection -------------------------------------------------------
51	
52	test("catalogueFacets: accessibility union sorted; price only counts explicit data", () => {
53	  const shows = [
54	    show({ accessibility: ["CAPTIONED", "AUDIO_DESCRIPTION"] }),
55	    show({ accessibility: ["CAPTIONED"] }),
56	    show({ free: true }), // free flag alone is not price *data*
57	  ];
58	  assert.deepEqual(catalogueFacets(shows), {
59	    accessibility: ["AUDIO_DESCRIPTION", "CAPTIONED"],
60	    hasPrice: false,
61	  });
62	  assert.equal(catalogueFacets([show({ price: "£10" })]).hasPrice, true);
63	  assert.deepEqual(catalogueFacets([]), { accessibility: [], hasPrice: false });
64	});
65	
66	// --- filters ---------------------------------------------------------------
67	
68	test("genre and subgenre filter exactly", () => {
69	  const comedy = show({ slug: "c", genre: "Comedy", subgenres: ["Stand-up"] });
70	  const theatre = show({ slug: "t", genre: "Theatre", subgenres: ["Devised"] });
71	  assert.deepEqual(filterShows([comedy, theatre], { genre: "Comedy" }), [comedy]);
72	  assert.deepEqual(filterShows([comedy, theatre], { subgenre: "Devised" }), [theatre]);
73	  assert.deepEqual(filterShows([comedy, theatre], { genre: "Comedy", subgenre: "Devised" }), []);
74	});
75	
76	test("maxAge keeps shows admitting that age: limit <= maxAge, unknown excluded", () => {
77	  const u = show({ slug: "u", ageRestriction: "ZERO" });
78	  const eight = show({ slug: "8", ageRestriction: "EIGHT" });
79	  const twelve = show({ slug: "12", ageRestriction: "TWELVE" });
80	  const unknown = show({ slug: "?", ageRestriction: null });
81	  assert.deepEqual(filterShows([u, eight, twelve, unknown], { maxAge: 8 }), [u, eight]);
82	  assert.deepEqual(filterShows([u, eight, twelve, unknown], { maxAge: 0 }), [u]);
83	  // No filter → unknown age passes through.
84	  assert.deepEqual(filterShows([unknown], {}), [unknown]);
85	});
86	
87	test("accessibility filter requires the declared option; undeclared excluded", () => {
88	  const captioned = show({ slug: "c", accessibility: ["CAPTIONED"] });
89	  const none = show({ slug: "n" });
90	  assert.deepEqual(filterShows([captioned, none], { accessibility: "CAPTIONED" }), [captioned]);
91	  assert.deepEqual(filterShows([captioned, none], { accessibility: "SIGNED" }), []);
92	});
93	
94	test("price 'free' and caps; unknown price excluded under any price filter", () => {
95	  const free = show({ slug: "f", free: true });
96	  const tenner = show({ slug: "10", price: "£10" });
97	  const twenty = show({ slug: "20", price: 20 });
98	  const unknown = show({ slug: "?" });
99	  assert.deepEqual(filterShows([free, tenner, twenty, unknown], { price: "free" }), [free]);
