// One reusable browser driver: node shot.mjs <url> <out.png> [step ...]
// Steps run in order:
//   upload:<selector>=<file>   set an <input type=file>
//   click:<selector>
//   fill:<selector>=<text>
//   wait:<ms>
//   waitfor:<selector>
//   eval:<js>                  run in the page
//   full                       full-page screenshot (default: viewport)
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const [url, out, ...steps] = process.argv.slice(2);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const errors = [];
page.on("console", (m) => {
  if (m.type() === "error" && !/favicon\.ico|ERR_CONNECTION_RESET/.test(m.text())) errors.push(m.text());
});
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto(url, { waitUntil: "networkidle" });
let full = false;
for (const step of steps) {
  const [kind, ...rest] = step.split(":");
  const arg = rest.join(":");
  if (kind === "upload") {
    const [sel, file] = arg.split("=");
    await page.setInputFiles(sel, file);
  } else if (kind === "click") {
    await page.click(arg);
  } else if (kind === "fill") {
    const i = arg.indexOf("=");
    await page.fill(arg.slice(0, i), arg.slice(i + 1));
  } else if (kind === "type") {
    const i = arg.indexOf("=");
    await page.type(arg.slice(0, i), arg.slice(i + 1), { delay: 30 });
  } else if (kind === "wait") {
    await page.waitForTimeout(Number(arg));
  } else if (kind === "waitfor") {
    await page.waitForSelector(arg);
  } else if (kind === "eval") {
    const r = await page.evaluate(arg);
    if (r !== undefined) console.log("eval:", JSON.stringify(r));
  } else if (kind === "full") {
    full = true;
  } else {
    throw new Error(`unknown step: ${step}`);
  }
}
await page.screenshot({ path: out, fullPage: full });
console.log(errors.length ? "console errors:\n" + errors.join("\n") : "no console errors");
await browser.close();

