export function hasActiveFilters(filters) {
  const f = filters || {};
  return (
    facetValues(f.genre).length > 0 ||
    facetValues(f.subgenre).length > 0 ||
    facetValues(f.accessibility).length > 0 ||
    typeof f.maxAge === "number" ||
    f.price === "free" ||
    typeof f.price === "number"
