input.old_string:
/* Upload summary (failure feedback only — the calendar takes over on success) */
.upload-summary {
  display: flex; align-items: center; gap: 14px;
  margin-top: 22px;
  border: 1px solid #c7ecd9; background: var(--ok-bg);
  border-radius: 12px; padding: 13px 16px;
}
.upload-summary.is-partial { border-color: #fde3b8; background: #fff8ea; }
.us-tick {
  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;
  display: grid; place-items: center; color: #fff; background: var(--ok);
}
.us-body { flex: 1; min-width: 0; }
.us-main { font-weight: 700; font-size: 0.95rem; color: var(--ok-text); }
.us-sub { font-size: 0.8rem; color: var(--muted); }
.us-file {
  flex: 0 0 auto; font-size: 0.74rem; font-weight: 600; color: var(--muted);
  background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px;
  white-space: nowrap;
}
.missing-list {
  margin: 8px 0 0; padding: 10px 14px; list-style: none;
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
  font-size: 0.82rem; color: var(--muted); max-height: 160px; overflow-y: auto;
}
.missing-list li { padding: 2px 0; }
.missing-list code { font-size: 0.8rem; color: var(--ink); }

/* "More settings" placeholder block (always visible) */
.more { margin-top: 22px; border-top: 1px solid var(--line); padding-top: 6px; }
.more-title {
  display: flex; align-items: center; gap: 8px;
  margin: 0; padding: 10px 4px; font-weight: 700; font-size: 0.9rem; color: var(--ink);
}
.more-hint { margin-left: auto; font-weight: 600; font-size: 0.74rem; color: #98a2b3; }
.more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 22px; padding: 8px 4px 14px; }
.more-field-label {
  display: block; text-transform: uppercase; letter-spacing: 0.05em;
  font-size: 0.68rem; font-weight: 700; color: var(--muted); margin: 0 0 7px;
}
.chips { display: flex; flex-wrap: wrap; gap: 6px; grid-column: 1 / -1; }
.chips-wrap { grid-column: 1 / -1; }
.chip {
  font-size: 0.78rem; font-weight: 600; padding: 6px 12px; border-radius: 999px;
  border: 1px solid var(--line); background: #fff; color: var(--muted);
}
.chip.is-on { border-color: var(--violet); color: var(--violet-dark); background: rgba(108, 76, 241, 0.07); }
.faux-input {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  font-size: 0.88rem; font-weight: 600;
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
  padding: 9px 12px; color: var(--ink);
}
.faux-input .fi-caret { color: var(--muted); font-size: 0.68rem; }

input.new_string:
/* Upload feedback. A usable file switches the board to the grid, so this panel
   only ever carries a problem — and reads like one. */
.upload-summary {
  display: flex; align-items: center; gap: 14px;
  max-width: 560px;
  border: 1px solid #f5c9c9; background: #fef3f2;
  border-radius: 12px; padding: 13px 16px;
}
.us-icon {
  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;
  display: grid; place-items: center; color: #fff; background: var(--warn);
}
.us-body { flex: 1; min-width: 0; text-align: left; }
.us-main { font-weight: 700; font-size: 0.95rem; color: #b42318; }
.us-sub { font-size: 0.8rem; color: var(--muted); }
.us-file {
  flex: 0 0 auto; max-width: 40%; font-size: 0.74rem; font-weight: 600; color: var(--muted);
  background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
/* Dropping a file we won't even try to read gets its own refusal state on the
   box itself, so the rejection lands where the pointer already is. */
.dropzone.is-reject { border-color: var(--warn); background: #fef3f2; }

