  transition: border-color 0.12s ease, box-shadow 0.12s ease;
}
.ss-bar:focus-within, .show-search.is-open .ss-bar {
  border-color: var(--violet);
  box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.13);
}
