  display: grid; place-items: center;
  font-size: 0.64rem; font-weight: 800; color: #fff; background: var(--violet);
}

/* The expanded line of search tools above the box. Each facet is a chip that
   drops a panel of checkable options — the same instrument the Now page's
   filters use, in this page's palette. */
.ss-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 8px; }
.filter-chip { position: relative; }
.chip-trigger {
  display: inline-flex; align-items: center; gap: 5px; max-width: 200px;
  font: inherit; font-size: 0.78rem; font-weight: 600; color: var(--ink);
  background: #fff; border: 1px solid var(--line); border-radius: 999px;
  padding: 6px 12px; cursor: pointer;
}
