/* The line between the category rows and the show rows. */
.ss-results .ss-row--facet:last-of-type { margin-bottom: 6px; }

/* ============ Availability calendar ============ */
/* `relative` so the colour key can sit in the card's own bottom padding rather
   than claiming a row of its own — see .cal-legend. */
.cal-card { position: relative; padding: 30px 28px 34px; }
.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
.cal-top-left { min-width: 0; max-width: 640px; }
.cal-title-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.cal-title {
  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
  letter-spacing: -0.01em; margin: 0 0 6px;
}
/* Collapse / expand the grid canvas. */
.cal-collapse {
  display: inline-flex; align-items: center; gap: 5px;
  font: inherit; font-size: 0.78rem; font-weight: 600; color: var(--muted);
  background: #fff; border: 1px solid var(--line); border-radius: 999px;
  padding: 4px 12px; cursor: pointer; margin-bottom: 6px;
}
.cal-collapse:hover { color: var(--ink); border-color: #d5d9e2; }
.cal-collapse .cc-caret { transition: transform 0.18s ease; }
#screen2.is-collapsed .cal-collapse .cc-caret { transform: rotate(-90deg); }
#screen2.is-collapsed .cal-wrap,
#screen2.is-collapsed .cal-legend { display: none; }

/* The favourites provenance line: what's loaded, plus quiet replace/clear
   actions — deliberately low-key, no button chrome, no accent colour. */
.fav-line {
  display: flex; align-items: baseline; gap: 4px 8px; flex-wrap: wrap;
  margin: 0; font-size: 0.85rem; color: var(--muted);
}
.fav-action {
  font: inherit; font-size: 0.82rem; color: var(--muted);
  background: none; border: none; padding: 0; cursor: pointer;
  text-decoration: underline; text-underline-offset: 2px;
  text-decoration-color: #c6cdda;
}
.fav-action:hover { color: var(--ink); text-decoration-color: currentColor; }
.fav-sep { color: #c6cdda; }

/* The payoff number — scheduled / in-window / favourites */
.hero-count { text-align: right; flex: 0 0 auto; }
.hc-num {
  font-weight: 800; font-size: 2.7rem; line-height: 1; letter-spacing: -0.02em;
  color: var(--violet-dark); white-space: nowrap;
}
.hc-num #hcIn { color: var(--muted); }
.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 1.7rem; }
.hc-num.bump { animation: countbump 0.4s ease; }
@keyframes countbump {
  0% { transform: scale(1); }
  45% { transform: scale(1.09); color: var(--violet); }
  100% { transform: scale(1); }
}
.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }

/* The availability-status legend colours mirror edfringe.com's own day-picker
   legend (see plan.js segClass / the --fr-* tokens below). */
.opt-select {
  font: inherit; font-size: 0.84rem; font-weight: 600; color: var(--ink);
  border: 1px solid var(--line); border-radius: 10px; background: #fff;
  padding: 7px 10px; cursor: pointer;
}
.opt-select:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
.btn-sm { padding: 8px 14px; font-size: 0.84rem; border-radius: 10px; box-shadow: 0 4px 12px rgba(108, 76, 241, 0.22); }
.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
.lg-avail i   { background: var(--fr-avail); }
.lg-2for1 i   { background: var(--fr-2for1-weave); }
.lg-preview i { background: var(--fr-preview); }
.lg-free i    { background: var(--fr-free); }
.lg-event i   { background: var(--fr-event); }
.lg-noalloc i { background: var(--fr-noalloc); }

/* --- The calendar canvas --- */
/* .cal-wrap is the scroll container: the sticky block (window-control rail +
   day header) stays at its top while the lane list scrolls beneath it. The
   toolbar/hero-count above are outside this container entirely, so they never
   scroll away either. */
.cal-wrap {
  position: relative; margin-top: 20px;
  /* Deliberately shallow: the calendar is now the "pick your window" step that
     feeds the planner below it, so it stays compact and scrolls internally
     rather than pushing the Plan card off-screen. */
  max-height: 38vh; overflow-y: auto; overflow-x: hidden;
  border-radius: 10px;
}
.cal-inner { position: relative; }

.cal-sticky { position: sticky; top: 0; z-index: 4; background: var(--paper); }

/* minmax(0, …) on the day track lets the 31 columns shrink to the available
   width instead of holding their content's min-width and forcing the whole grid
   (day header + lanes) to overflow — which clipped the "In plan" column and the
   window flags on a narrower page. */
.cal-row { display: grid; grid-template-columns: 184px minmax(0, 1fr) 104px; gap: 0 12px; align-items: center; }

.cal-head { border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
.days { display: grid; grid-template-columns: repeat(31, minmax(0, 1fr)); gap: 3px; }
.day-col { text-align: center; line-height: 1.15; }
.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
.day-col.pre .day-num, .day-col.pre .day-dow { color: #cfd4de; }

