330	function handleFile(file) {
331	  if (!file) return;
332	  const reader = new FileReader();
333	  reader.onload = () => processFavouritesText(String(reader.result || ""), file.name);
334	  reader.onerror = () => {
335	    console.error("Fringe Planner: failed to read file", reader.error);
336	    alert("Couldn't read that file — please try again.");
337	  };
338	  reader.readAsText(file);
339	}
340	
341	function processFavouritesText(text, filename) {
342	  const slugs = parseFavourites(text);
343	  const savedAt = Date.now();
344	  if (slugs.length > 0) saveFavourites(slugs, filename, savedAt);
345	  applyFavourites(slugs, filename, savedAt, { scroll: true });
346	}
347	
348	async function applyFavourites(slugs, filename, savedAt, { scroll = false, keepForced = false, keepWindow = false } = {}) {
349	  state.pendingUpload = { slugs, filename, savedAt, scroll };
350	
351	  let index;
352	  try {
353	    index = await ensureData();
354	  } catch (err) {
355	    console.error("Fringe Planner: failed to load show data", err);
356	    $("errorDetail").textContent =
357	      "Check your connection and try again. (" + (err && err.message ? err.message : "unknown error") + ")";
358	    $("errorState").hidden = false;
359	    return;
360	  }
361	
362	  const { matched, missingSlugs } = matchFavourites(slugs, index);
363	  state.pendingUpload = null;
364	
365	  state.favSlugs = slugs.slice();
366	  state.totalFavourites = slugs.length;
367	  state.matched = matched;
368	  state.missingSlugs = missingSlugs;
369	  state.filename = filename;
370	  state.savedAt = savedAt;
371	  // A fresh upload clears must-sees; an add/remove keeps the pins still on the grid.
372	  const survivingSlugs = new Set(matched.map((s) => s.slug));
373	  state.forced = keepForced
374	    ? new Map([...state.forced].filter(([slug]) => survivingSlugs.has(slug)))
375	    : new Map();
376	
377	  syncSearchStars(); // the search popup's stars mirror the grid
378	
379	  if (matched.length > 0) {
380	    // A fresh upload starts from the default window; a one-by-one add/remove is
381	    // a quiet tweak to a grid in use, so it leaves the user's dates alone.
382	    if (!keepWindow) {
383	      state.d0 = DEFAULT_D0;
384	      state.d1 = DEFAULT_D1;
385	    }
386	    renderFavLine();
387	    buildCalendar(); // builds the lanes DOM…
388	    refresh(); // …then the first plan + verdicts + hero
389	    $("screen1").hidden = true;
390	    showCalendar({ scroll });
391	  } else {
392	    renderUploadSummary();
393	    $("screen1").hidden = false;
394	    $("screen2").hidden = true;
395	  }
396	}
