}

/** …and back: the empty board, with the drop stage in the body. */
function showIntake() {
  $("calWrap").hidden = true;
  $("calLegend").hidden = true;
  $("intakeStage").hidden = false;
  $("clearFavBtn").hidden = true;
  $("planPanel").hidden = true;
  $("lanes").innerHTML = "";
  state.laneRefs = [];
  renderCounts();
  $("board").scrollIntoView({ behavior: "smooth", block: "start" });
}

