  shown: 0,
  debounce: null,
  venues: [], // [{value: code, label: name}] — filled once the catalogue lands
  // One entry per facet: a Set for the multi-select lists, a string ("" = not
  // set) for the two single-answer ones.
  filters: {
    genre: new Set(),
    subgenre: new Set(),
    accessibility: new Set(),
    venue: new Set(),
    age: "",
    price: "",
  },
};

